head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.onpageload = function () {
};



// 화면상 실제로 펼쳐져 있는 패널을 내용 영역 높이로 판별한다.
scwin.getVisibleOpenPanels = function (objTarget) {
    var arrOpen = [];
    var arrPanel = ["panels1", "panels2", "panels3"];
    for (var i = 0; i < arrPanel.length; i++) {
        var objContent = document.getElementById(objTarget.id + "_panel_" + arrPanel[i] + "_panelContent_panelContent" + (i + 1));
        if (objContent !== null && objContent.getBoundingClientRect().height > 1) {
            arrOpen.push(arrPanel[i]);
        }
    }
    return arrOpen;
};



scwin.btn_check_onclick = function (e) {
    var arrVisible = scwin.getVisibleOpenPanels(target1);

    var objOne = target1.getOpenPanelInfo();
    var arrList = target1.getOpenPanelListInfo();

    var arrListId = [];
    if (arrList !== null) {
        for (var i = 0; i < arrList.length; i++) {
            arrListId.push(arrList[i].id);
        }
    }

    scwin.setReturnValue("=====collapseAll=true / unCollapseAll=true 로 렌더된 상태=====");
    scwin.setReturnValue("    화면에서 펼쳐진 패널 : " + (arrVisible.length === 0 ? "없음 (모두 닫힘)" : arrVisible.join(", ")));
    scwin.setReturnValue("    getOpenPanelInfo() : " + ((objOne === null || objOne.id === undefined) ? "열린 패널 없음" : objOne.id));
    scwin.setReturnValue("    getOpenPanelListInfo() 건수 : " + arrListId.length);
    scwin.setReturnValue("    getOpenPanelListInfo() 내용 : " + (arrListId.length === 0 ? "없음" : arrListId.join(", ")));
    scwin.setReturnValue("");

    scwin.setReturnValue("----- 판정 -----");
    if (arrVisible.length === 0 && arrListId.length > 0) {
        scwin.setReturnValue("화면은 모두 닫혀 있는데 조회 API 는 열린 패널이 있다고 반환한다 (" + arrListId.length + "건)");
    } else if (arrVisible.length === 0 && arrListId.length === 0) {
        scwin.setReturnValue("화면과 조회 API 가 일치한다 (모두 닫힘)");
    } else {
        scwin.setReturnValue("화면에 펼쳐진 패널이 있다");
    }
    scwin.setReturnValue("");
};
